//! Whole API policy over actual raw CODE loans. Returned DATA is unsealed;
//! only the concrete host can issue the three exhausted original phases.
//! Original scanner/regex helper scratch remains its existing qualified baseline.
use crate::{api_policy::{self,FwFacts},captured_raw_file::{Config,RawPolicyViews},captured_generator_budget::Budget,captured_reactive_reads::Failure,reactive_raw_policy_pages::RawPolicyPages,key_policy_control::{self as kc,Control},captured_allow_annotations::{Operation,PatternOperation},lint::{Site,AllowUse}};
use std::{collections::BTreeMap,io,sync::{Arc,LazyLock}};
fn policy()->&'static api_policy::Api{static POLICY:LazyLock<api_policy::Api>=LazyLock::new(api_policy::Api::new);&POLICY}
pub fn metadata()->&'static crate::lint::Meta{&api_policy::META}
fn oom(b:&Budget)->Failure{b.deny();Failure::Operational(io::ErrorKind::OutOfMemory.into())}
pub(crate) fn checked(b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{b.require().map_err(|_|oom(b))?;poll()?;b.require().map_err(|_|oom(b))}
struct Phase{budget:Arc<Budget>,complete:bool}impl Drop for Phase{fn drop(&mut self){if !self.complete{self.budget.keep_failed_scratch()}}}
pub(crate) fn node(b:&Budget)->Result<(),Failure>{b.charge(2048).map_err(|_|oom(b))}
pub(crate) fn own(b:&Budget,poll:&dyn Fn()->io::Result<()>,s:&str)->Result<String,Failure>{kc::own(&mut Operation{budget:b,poll},s)}
pub(crate) fn row<T>(b:&Budget,poll:&dyn Fn()->io::Result<()>,rows:&mut Vec<T>)->Result<(),Failure>{crate::reactive_dependency_fold::row(&mut Operation{budget:b,poll},rows)}
fn fact_bound(f:&FwFacts)->Option<usize>{let mut n=std::mem::size_of::<FwFacts>().checked_add(f.fields.len().checked_mul(4*std::mem::size_of::<(String,Vec<String>)>())?)?;for(name,types)in &f.fields{n=n.checked_add(name.len().checked_mul(4)?)?.checked_add(4096)?.checked_add(types.len().checked_mul(4*std::mem::size_of::<String>())?)?;for ty in types{n=n.checked_add(ty.len().checked_mul(4)?)?.checked_add(128)?;}}for(owner,members)in &f.members{n=n.checked_add(2048)?.checked_add(owner.len().checked_mul(4)?)?;for(name,ty)in members{n=n.checked_add(2048)?.checked_add(name.len().checked_add(ty.len())?.checked_mul(4)?)?;}}for(name,ty)in &f.globals{n=n.checked_add(2048)?.checked_add(name.len().checked_add(ty.len())?.checked_mul(4)?)?;}Some(n)}
fn clone_facts(f:&FwFacts,b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<FwFacts,Failure>{checked(b,poll)?;let bound=fact_bound(f).ok_or_else(||oom(b))?;b.charge(bound).map_err(|_|oom(b))?;let copy=f.clone();if copy.fields.capacity()>f.fields.len().saturating_mul(4)||copy.fields.iter().zip(&f.fields).any(|((_,types),(_,old))|types.capacity()>old.len().saturating_mul(4)){return Err(oom(b))}Ok(copy)}
pub struct ApiData{pub(crate) sites:Vec<Site>,pub(crate) source_text:Vec<String>,pub(crate) allow_used:Vec<AllowUse>,pub(crate) digests:BTreeMap<String,[u8;20]>}
impl ApiData{pub fn sites(&self)->&[Site]{&self.sites}pub fn source_text(&self)->&[String]{&self.source_text}pub fn allow_used(&self)->&[AllowUse]{&self.allow_used}pub fn allow_source_digest(&self,rel:&str)->Option<&[u8;20]>{self.digests.get(rel)}}
struct Reporter<'a>{data:&'a mut ApiData,file:&'a crate::tree::SourceFile,budget:&'a Budget,local:&'a Budget,poll:&'a dyn Fn()->io::Result<()>,patterns:Option<&'a dyn crate::native_pattern::Provider>,fixture:Option<&'a crate::raw_fixture_policy::Fixture<'a>>,allow_start:usize,error:Option<Failure>}
impl Reporter<'_>{
 fn fail(&mut self,actual:Failure){match actual{Failure::Operational(actual)if self.fixture.is_some()=>{self.fixture.unwrap().note_operational(actual);self.error=Some(Failure::Unsupported("actual reporter IO retained by same scanner owner".into()));},actual=>self.error=Some(actual)}}
 fn allowed_using(&mut self,line:usize)->Result<bool,Failure>{checked(self.budget,self.poll)?;let raw=self.file.raw();let mut control=PatternOperation{budget:self.local,poll:self.poll,patterns:self.patterns};let mut kept=None;if line>=1&&line<=raw.num_lines(){if let Some(code)=crate::allow::keeps_with(raw.line(line),"api",&mut control)?{kept=Some((line,code));}}if kept.is_none()&&line>=2{let above=raw.line(line-1);if crate::util::py_lstrip(above).starts_with("//"){if let Some(code)=crate::allow::keeps_with(above,"api",&mut control)?{kept=Some((line-1,code));}}}let Some((at,code))=kept else{return Ok(false)};let code=code.unwrap_or_default();let number=u32::try_from(at).map_err(|_|oom(self.budget))?;if !self.data.allow_used[self.allow_start..].iter().any(|u|u.rel==self.file.rel&&u.line==number&&u.name=="api"&&u.code==code){row(self.budget,self.poll,&mut self.data.allow_used)?;self.data.allow_used.push(AllowUse{rel:own(self.budget,self.poll,&self.file.rel)?,line:number,name:own(self.budget,self.poll,"api")?,code:own(self.budget,self.poll,&code)?});}if !self.data.digests.contains_key(self.file.rel.as_str()){node(self.budget)?;self.data.digests.insert(own(self.budget,self.poll,&self.file.rel)?,crate::captured_raw_file::source_allow_digest(self.file));}Ok(true)}
 fn site_using(&mut self,rule:&str,line:usize)->Result<(),Failure>{checked(self.budget,self.poll)?;row(self.budget,self.poll,&mut self.data.sites)?;row(self.budget,self.poll,&mut self.data.source_text)?;let raw=self.file.line(line);let max=raw.len().checked_mul(4).and_then(|n|n.checked_add(256)).ok_or_else(||oom(self.budget))?;self.budget.charge(max).map_err(|_|oom(self.budget))?;let text=crate::util::normalize_ws(raw);if text.capacity()>max{return Err(oom(self.budget))}self.data.source_text.push(text);self.data.sites.push(Site{rule:own(self.budget,self.poll,rule)?,rel:own(self.budget,self.poll,&self.file.rel)?,line:u32::try_from(line).map_err(|_|oom(self.budget))?,msg:String::new(),key:String::new(),ident:String::new()});Ok(())}
 fn finish(self)->Result<(),Failure>{if let Some(actual)=self.error{return Err(actual)}checked(self.local,self.poll)?;checked(self.budget,self.poll)}
}
impl api_policy::Reporter for Reporter<'_>{fn allowed(&mut self,line:usize)->bool{if self.error.is_some(){return true}match self.allowed_using(line){Ok(value)=>value,Err(actual)=>{self.fail(actual);true}}}fn site(&mut self,rule:&str,line:usize){if self.error.is_none(){if let Err(actual)=self.site_using(rule,line){self.fail(actual);}}}}

pub(crate) fn empty()->ApiData{ApiData{sites:Vec::new(),source_text:Vec::new(),allow_used:Vec::new(),digests:BTreeMap::new()}}
struct Batch{relative:String,data:ApiData}
pub(crate) fn reserve_append<T>(b:&Budget,poll:&dyn Fn()->io::Result<()>,into:&mut Vec<T>,count:usize)->Result<(),Failure>{checked(b,poll)?;let wanted=into.len().checked_add(count).ok_or_else(||oom(b))?;if wanted<=into.capacity(){return Ok(())}let cap=wanted.checked_mul(4).ok_or_else(||oom(b))?;b.charge(cap.checked_mul(std::mem::size_of::<T>()).and_then(|n|n.checked_add(128)).ok_or_else(||oom(b))?).map_err(|_|oom(b))?;into.try_reserve_exact(wanted-into.len()).map_err(|_|oom(b))?;if into.capacity()>cap{return Err(oom(b))}Ok(())}
pub(crate) fn append(data:&mut ApiData,mut from:ApiData,root:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{reserve_append(root,poll,&mut data.sites,from.sites.len())?;reserve_append(root,poll,&mut data.source_text,from.source_text.len())?;reserve_append(root,poll,&mut data.allow_used,from.allow_used.len())?;data.sites.append(&mut from.sites);data.source_text.append(&mut from.source_text);data.allow_used.append(&mut from.allow_used);for(label,digest)in from.digests{checked(root,poll)?;if !data.digests.contains_key(&label){node(root)?;}data.digests.insert(label,digest);}Ok(())}
/// Shared existing field index loan; DATA callbacks cannot mint source completion.
pub(crate) fn with_field_index<R>(pages:&dyn RawPolicyPages,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,consume:impl FnOnce(&crate::dm::field_write::FwlIndex,&Arc<Budget>)->Result<R,Failure>)->Result<R,Failure>{with_field_index_patterns(pages,root,poll,None,consume)}
pub(crate) fn with_field_index_patterns<R>(pages:&dyn RawPolicyPages,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:Option<&dyn crate::native_pattern::Provider>,consume:impl FnOnce(&crate::dm::field_write::FwlIndex,&Arc<Budget>)->Result<R,Failure>)->Result<R,Failure>{
 checked(root,poll)?;let mut phase=Phase{budget:Budget::scoped_temporaries(root).map_err(|_|oom(root))?,complete:false};let b=&phase.budget;let pending=(||{
  let mut rows=Vec::new();if !pages.for_each(&mut|relative,views:RawPolicyViews<'_>|{checked(b,poll)?;let file=views.source_file()?;if file.rel!=relative{return Err("API original relative path differs".into())}let local=Budget::scoped_temporaries(root).map_err(|_|oom(root))?;let native=patterns.map(|provider|crate::raw_fixture_policy::Fixture::scanned(&local,poll,provider,file)).transpose().map_err(pattern_failure)?;let legacy=crate::raw_fixture_policy::Fixture::legacy();let fixture=native.as_ref().unwrap_or(&legacy);let temporary=api_policy::fw_facts_with_fixture(file,fixture);if let Some(actual)=fixture.take_scan_failure(){return Err(pattern_failure(actual))}let retained=clone_facts(&temporary,b,poll)?;row(b,poll,&mut rows)?;rows.push((own(b,poll,relative)?,retained));drop(temporary);checked(views.allocation_budget(root),poll)?;Ok(true)})?{return Err("API global field phase stopped before EOF".into())}
  // Tree::select is sorted by UTF8 relative path. Do not infer its precedence
  // from a platform directory or capture-container iteration order.
  b.charge(rows.len().checked_mul(4*std::mem::size_of::<(String,FwFacts)>()).and_then(|n|n.checked_add(128)).ok_or_else(||oom(b))?).map_err(|_|oom(b))?;rows.sort_by(|a,b|a.0.cmp(&b.0));
  let mut facts=Vec::new();reserve_append(b,poll,&mut facts,rows.len())?;for(_,fact)in rows{checked(b,poll)?;facts.push(fact);}
  let mut merge=4096usize;for fact in &facts{checked(b,poll)?;merge=merge.checked_add(fact_bound(fact).ok_or_else(||oom(b))?.checked_mul(2).ok_or_else(||oom(b))?).ok_or_else(||oom(b))?;}b.charge(merge).map_err(|_|oom(b))?;let index=api_policy::merge_index(&facts);
let result=consume(&index,b)?;drop(index);drop(facts);Ok(result)
})();if matches!(&pending,Err(Failure::Operational(_))){return pending}checked(root,poll)?;phase.complete=pending.is_ok();drop(phase);pending
}
pub fn collect(pages:&dyn RawPolicyPages,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<ApiData,Failure>{collect_using(pages,config,root,poll,None)}
pub fn collect_with_patterns(pages:&dyn RawPolicyPages,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:&dyn crate::native_pattern::Provider)->Result<ApiData,Failure>{collect_using(pages,config,root,poll,Some(patterns))}
fn collect_using(pages:&dyn RawPolicyPages,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:Option<&dyn crate::native_pattern::Provider>)->Result<ApiData,Failure>{with_field_index_patterns(pages,root,poll,patterns,|index,b|{
  let fields=if patterns.is_none(){Some(index.all_fields())}else{None};let mut data=empty();
  for field_phase in [false,true]{
   let mut batches=Vec::new();if !pages.for_each(&mut|relative,views|{checked(b,poll)?;if config.policy_path_exempt("api","",relative){return Ok(true)}let file=views.source_file()?;if file.rel!=relative{return Err("API selected relative path differs".into())}let mut file_data=empty();let local=Budget::scoped_temporaries(root).map_err(|_|oom(root))?;let native=patterns.map(|provider|crate::raw_fixture_policy::Fixture::scanned(&local,poll,provider,file)).transpose().map_err(pattern_failure)?;let legacy=crate::raw_fixture_policy::Fixture::legacy();let fixture=native.as_ref().unwrap_or(&legacy);let mut out=Reporter{data:&mut file_data,file,budget:root,local:views.allocation_budget(root),poll,patterns,fixture:native.as_ref(),allow_start:0,error:None};if field_phase{let lines=if native.is_some(){let selected=index.all_fields_with_fixture(fixture);if let Some(actual)=fixture.take_scan_failure(){return Err(pattern_failure(actual))}let selected=selected.map_err(Failure::Unsupported)?;index.check_with_fixture(&selected,&file.code().text,fixture)}else{index.check(fields.as_ref().expect("actual original compatibility fields"),&file.code().text)};if let Some(actual)=fixture.take_scan_failure(){return Err(pattern_failure(actual))}for line in lines{checked(b,poll)?;if !out.allowed_using(line)?{out.site_using("field_write",line)?;}}}else{if native.is_some(){let actual=api_policy::Api::with_fixture(fixture);let pending=match actual{Ok(actual)=>{actual.scan_file_with_fixture(file,&mut out,fixture);Ok(())},Err(message)=>Err(Failure::Unsupported(message))};if let Some(actual)=fixture.take_scan_failure(){return Err(pattern_failure(actual))}pending?;}else{policy().scan_file(file,&mut out);}}if let Some(actual)=fixture.take_scan_failure(){return Err(pattern_failure(actual))}out.finish()?;row(b,poll,&mut batches)?;batches.push(Batch{relative:own(b,poll,relative)?,data:file_data});Ok(true)})?{return Err("API selected policy phase stopped before EOF".into())}
   b.charge(batches.len().checked_mul(4*std::mem::size_of::<Batch>()).and_then(|n|n.checked_add(128)).ok_or_else(||oom(b))?).map_err(|_|oom(b))?;batches.sort_by(|a,b|a.relative.cmp(&b.relative));for batch in batches{checked(b,poll)?;append(&mut data,batch.data,root,poll)?;}
  }
  checked(b,poll)?;drop(fields);Ok(data)
})}

fn pattern_failure(actual:crate::derived_selftest_policy::Failure)->Failure{match actual{crate::derived_selftest_policy::Failure::Operational(actual)=>Failure::Operational(actual),crate::derived_selftest_policy::Failure::Assertion(message)=>Failure::Unsupported(message)}}

#[cfg(test)]mod page_scratch_scope_controls{
 use super::*;use crate::{captured_raw_file::File,captured_raw_policy::Configuration};use std::cell::Cell;
 struct Pages{file:File,passes:Cell<usize>,fail:bool}
 impl RawPolicyPages for Pages{
  fn for_each(&self,visit:&mut dyn FnMut(&str,RawPolicyViews<'_>)->Result<bool,Failure>)->Result<bool,Failure>{self.passes.set(self.passes.get()+1);if !self.file.with_policy_views(visit)?{return Ok(false)}if self.fail{return Err(Failure::Operational(io::Error::from_raw_os_error(1450)))}Ok(true)}
 }
 fn pages(fail:bool)->Pages{let root=std::env::current_dir().unwrap().join("api-page-scratch-data");let file=File::capture(&root,&root.join("code/probe.dm"),dm_preprocess::SourceText::from("/datum/api_probe\n    var/value = 1\n")).unwrap();Pages{file,passes:Cell::new(0),fail}}
 #[test]fn api_global_and_both_scan_phases_use_sibling_page_scratch_under_same_one_mib(){
  let pages=pages(false);let budget=Budget::new(1<<20).unwrap();let config=Config::capture(Configuration::ProvenMissing).unwrap();
  // This exercises the actual shared API fold and original File policy loans.
  // It grants no Source completeness and does not substitute for host tests.
  let data=collect(&pages,&config,&budget,&||Ok(())).unwrap();assert_eq!(pages.passes.get(),3,"field-index collection and both policy phases must really execute");assert!(data.sites().is_empty());assert!(!budget.denied());assert!(budget.used()<1<<20);
 }
 #[test]fn api_page_provider_first_io_survives_failed_scratch_and_fresh_fold_recovers(){
  let bad=pages(true);let config=Config::capture(Configuration::ProvenMissing).unwrap();let budget=Budget::new(1<<20).unwrap();
  let error=collect(&bad,&config,&budget,&||Ok(())).err().unwrap();assert!(matches!(error,Failure::Operational(ref e)if e.raw_os_error()==Some(1450)));assert_eq!(bad.passes.get(),1);
  let good=pages(false);let fresh=Budget::new(1<<20).unwrap();assert!(collect(&good,&config,&fresh,&||Ok(())).is_ok());assert_eq!(good.passes.get(),3);
 }
}
